'use client'

import Link from 'next/link'
import Image from 'next/image'
import toast, { Toaster } from 'react-hot-toast'
import { Suspense } from 'react'
import { useEffect, useState } from 'react'
import { useFormStatus } from 'react-dom'
import ABI from './../../../abi/giftmoji.json'
import Loading from '../../../components/Loading'
import { useAuth, provider } from '../../../contexts/AuthContext'
import Web3 from 'web3'
import moment from 'moment-timezone'
import DefaultPFP from './../../../public/default-pfp.svg'
import Shimmer from '../../../helper/Shimmer'

import styles from './Profiles.module.scss'

export default function Profiles() {
  const [emoji, setEmoji] = useState([])
  const [reaction, setReaction] = useState([])
  const [user, setUser] = useState([])
  // const auth = useAuth()
  const { web3, contract } = initContract()
  const web3Readonly = new Web3(process.env.NEXT_PUBLIC_LUKSO_PROVIDER)
  const _ = web3Readonly.utils
  const contractReadonly = new web3Readonly.eth.Contract(ABI, process.env.NEXT_PUBLIC_CONTRACT)

  const fetchData = async (dataURL) => {
    let requestOptions = {
      method: 'GET',
      redirect: 'follow',
    }
    const response = await fetch(`${dataURL}`, requestOptions)
    if (!response.ok) throw new Response('Failed to get data', { status: 500 })
    return response.json()
  }

  // function numberToBytes32(number) {
  //   const hex = web3Readonly.utils.toHex(number);
  //   return web3Readonly.utils.padLeft(hex, 64);
  // }

  const getChillwhaleData = async (addresses) => {
    const myHeaders = new Headers()
    myHeaders.append('Content-Type', `application/json`)
    myHeaders.append('Accept', `application/json`)

    const requestOptions = {
      method: 'POST',
      headers: myHeaders,
      body: JSON.stringify({
        query: `query MyQuery {
  Asset(
    limit: 30
    where: {isLSP7: {_eq: false}, id: {_eq: "0x86e817172b5c07f7036bf8aa46e2db9063743a83"}}
  ) {
    id
    isLSP7
    lsp4TokenName
    lsp4TokenSymbol
    lsp4TokenType
    name
    totalSupply
    owner_id
    tokens(where: {formattedTokenId: {_in: ${JSON.stringify(addresses)}}}) {
      id
      formattedTokenId
      name
      images(limit: 1) {
        src
      }
      holders {
        profile_id
        profile {
          fullName
          profileImages(limit: 1) {
            src
          }
        }
      }
    }
  }
}`,
      }),
    }
    const response = await fetch(`${process.env.NEXT_PUBLIC_API_ENDPOINT}`, requestOptions)
    if (!response.ok) {
      throw new Response('Failed to ', { status: 500 })
    }
    const data = await response.json()
    return data
  }
  const getAllEmoji = async () => await contractReadonly.methods.getAllEmoji().call()

  const getAllUserReaction = async () => await contractReadonly.methods.getAllUserReaction(`0x0D5C8B7cC12eD8486E1E0147CC0c3395739F138d`).call()//${auth.contextAccounts[0]}

  const getProfiles = async (addresses) => {
    const myHeaders = new Headers()
    myHeaders.append('Content-Type', `application/json`)
    myHeaders.append('Accept', `application/json`)

    const requestOptions = {
      method: 'POST',
      headers: myHeaders,
      body: JSON.stringify({
        query: `query MyQuery {
  Profile(where: {id: {_in: ${JSON.stringify(addresses)}}}) {
    name
    tags
    description
    fullName
    id
    isEOA
    isContract
    src
    profileImages {
      src
    }
  }
}`,
      }),
    }
    const response = await fetch(`${process.env.NEXT_PUBLIC_API_ENDPOINT}`, requestOptions)
    if (!response.ok) {
      throw new Response('Failed to ', { status: 500 })
    }
    const data = await response.json()
    return data
  }

  useEffect(() => {
    getAllEmoji().then((res) => {
      console.log(res)
      if (res.length < 1) return
      setEmoji(res)
    })

    getAllUserReaction().then(async (reactionData) => {
      console.log(reactionData)
      if (reactionData.length < 1) return
      setReaction(reactionData)

      let senders = []
      reactionData.forEach(item => senders.push(item.sender.toLowerCase()))
      console.log(senders)

      getProfiles(senders).then(res => {
        console.log(res)
        let users = []
        res.data.Profile.forEach(profile => {
          users.push(Object.assign(profile, reactionData))
        })
        setUser(users)
      })

      // let responses_with_profile = []
      // await Promise.all(
      //   res.map(async (response, i) => {
      //     return getProfile(response.sender).then((profile) => {
      //       responses_with_profile.push(Object.assign(profile, response))
      //     })
      //   })
      // )
    })
  }, [])

  //       {reaction && reaction.sort((a, b) => web3Readonly.utils.toNumber(b.dt) - web3Readonly.utils.toNumber(a.dt)).map((item, i) => {
  return (
    <div className={`${styles.page} ms-motion-slideDownIn`}>
      {user.length > 0 && user.map((item, i) => {
        return (
          <div key={i} className={`card`}>
            <div key={i} className={`card__body d-flex flex-row align-items-center justify-content-between`}>
              <div className={`d-flex flex-row align-items-center justify-content-between`}>
                <a target={`_blank`} href={`https://universaleverything.io/${item.sender}`}>
                  {item.fullName}
                </a>
              </div>
              <div className={`d-flex flex-column align-items-center justify-content-between`}>
                <span className={`badge badge-danger badge-pill`}>
                  <span>⏣ </span>
                  <span>{_.fromWei(item.price, `ether`)}</span>
                </span>
                <small className={`text-secondary rounded`}>{moment.unix(web3Readonly.utils.toNumber(item.dt)).utc().fromNow()}</small>
              </div>
            </div>
          </div>
        )
      }
      )}
    </div>
  )
}